var response = await client.DashboardSections.GetDashboardSectionAsync("blog",
    new Dictionary<string, object?> { ["duration"] = "last_7_days" });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
Console.WriteLine($"{body["section"]} {body["comments_to_moderate"]}");
var drafts = (IReadOnlyDictionary<string, object?>)body["drafts_to_publish"]!;
Console.WriteLine(drafts["count"]);
foreach (var viewed in ((IReadOnlyList<object?>)body["most_viewed_posts"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{viewed["views"]}");
